sed -i 's/<\/body>/<script>\nfunction showPRDMock(id) {\n  const el = document.getElementById("prd-mock-content");\n  if(id === "prd") {\n    el.innerHTML = "<h1>Product Requirements Document<\/h1><p><strong>Status:<\/strong> Approved | <strong>Version:<\/strong> 1.0<\/p><h2>1. Executive Summary<\/h2><p>Puppet Master is a cross-platform desktop IDE designed to orchestrate AI agents for automated coding. It leverages Rust and Slint for a highly responsive user experience.<\/p><h2>2. Functional Requirements<\/h2><ul><li>FR1: The system shall support 4 tier phases for execution: Phase, Task, Subtask, Iteration.<\/li><li>FR2: It must integrate natively with multiple providers: Cursor, Gemini, Codex, Claude Code, Copilot.<\/li><li>FR3: A visual node graph (DAG) representation of tasks must be provided.<\/li><li>FR4: Must include a multi-agent interview wizard for capturing requirements.<\/li><\/ul><h2>3. Non-Functional Requirements<\/h2><ul><li>NFR1: Native performance with application launch time under 500ms.<\/li><li>NFR2: The UI framework must be based on Slint for declarative performance.<\/li><li>NFR3: Agent memory scaling must not exceed token quotas (budget caps must be supported).<\/li><\/ul><h2>4. Multi-Pass Review Process<\/h2><p>The system integrates an automated multi-pass document validation and canonical alignment to ensure the PRD conforms strictly to the schema before any code execution starts.<\/p><h2>5. Out of Scope<\/h2><p>Mobile application and cloud deployment orchestration are deferred to version 2.0.<\/p>";\n  } else if(id === "seeds") {\n    el.innerHTML = "<h1>Contract Seeds<\/h1><p>These JSON artifacts lock in the decisions for the execution phase.<\/p><pre style=\\"background:var(--surface); padding:var(--md); font-family:monospace; font-size:11px;\\">{\\n  \\"schema_version\\": \\"1.0\\",\\n  \\"tier_config\\": {\\n    \\"auto_approve\\": false,\\n    \\"branching\\": \\"feature\\"\\n  }\\n}<\/pre>";\n  } else if(id === "arch") {\n    el.innerHTML = "<h1>Architecture Documentation<\/h1><h2>1. Core Systems<\/h2><p>We are using a Rust backend connected to a Slint UI via channels. Persistent state is maintained using `redb`.<\/p><h2>2. Component Diagram<\/h2><div class=\\"mock-mermaid\\">graph TD;<br>UI[Slint Window] -->|Events| Backend[Rust Core];<br>Backend --> DB[(Redb)];<br>Backend --> Agents{{Agent Subsystem}};<br><\/div>";\n  }\n  document.querySelectorAll(".prd-pill").forEach(p => p.classList.remove("active"));\n  document.getElementById("pill-" + id).classList.add("active");\n}\n\nfunction showExecMock(id) {\n  const el = document.getElementById("exec-mock-content");\n  if(id === "exec") {\n    el.innerHTML = "<h1>Execution Plan<\/h1><h2>Phase 1: Foundation<\/h2><p><strong>Subagent:<\/strong> architect-reviewer<\/p><p>- Initialize Rust binary crate and workspace.<br>- Setup Redb persistence schema and initial migrations.<br>- Add standard `cargo fmt` and `clippy` checks to verification gates.<\/p><h2>Phase 2: GUI Core<\/h2><p><strong>Subagent:<\/strong> slint-engineer<\/p><p>- Stub out the main `AppWindow` in Slint.<br>- Implement bridging channels between the Rust core and UI.<br>- Compile dummy placeholder screens for Dashboard and Chat.<\/p><h2>Phase 3: Agent Orchestration<\/h2><p><strong>Subagent:<\/strong> backend-developer<\/p><p>- Create state machine logic for Phase\/Task\/Subtask execution.<br>- Wire in the Cursor CLI and Claude Code CLI providers.<br>- Set up concurrency limiters and rate-limit backoff handling.<\/p><h2>Phase 4: Integration & Tests<\/h2><p><strong>Subagent:<\/strong> qa-engineer<\/p><p>- Write end-to-end tests for orchestrator state transitions.<br>- Ensure GUI builds successfully headless for CI verification.<\/p>";\n  } else if(id === "manifest") {\n    el.innerHTML = "<h1>Acceptance Manifest<\/h1><p>This manifest guarantees exactly what needs to be verified before merging the task.<\/p><pre style=\\"background:var(--surface); padding:var(--md); font-family:monospace; font-size:11px;\\">{\\n  \\"gates\\": [\\n    { \\"id\\": \\"GATE-001\\", \\"type\\": \\"syntax\\", \\"command\\": \\"cargo check\\" },\\n    { \\"id\\": \\"GATE-002\\", \\"type\\": \\"tests\\", \\"command\\": \\"cargo test\\" },\\n    { \\"id\\": \\"GATE-003\\", \\"type\\": \\"headless_ui\\", \\"command\\": \\"npm run test:ui\\" }\\n  ],\\n  \\"artifacts\\": [\\n    \\"src\/main.rs\\",\\n    \\"ui\/app.slint\\"\\n  ]\\n}<\/pre>";\n  }\n  document.querySelectorAll(".exec-pill").forEach(p => p.classList.remove("active"));\n  document.getElementById("pill-" + id).classList.add("active");\n}\n<\/script>\n<\/body>/' Concepts/PuppetMasterDashComp.html
